function normalize(str) {
  if (!str) return '';
  return String(str)
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9 ]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

const STOP_WORDS = [
  'ltda', 'eireli', 'epp', 'me', 'sa', 'ss', 'sociedade', 'empresa',
  'comercio', 'comercial', 'industria', 'industrial', 'servico', 'servicos',
  'solucao', 'solucoes', 'grupo', 'brasil', 'do', 'da', 'de', 'dos', 'das', 'e'
];

function tokenize(str) {
  return normalize(str).split(' ').filter(t => t.length > 2 && !STOP_WORDS.includes(t));
}

const input = $input.first().json || {};
const rawNome = String(input.nome || '').trim();
const nomeNorm = normalize(rawNome);
const tokens = tokenize(rawNome);

return [{
  json: {
    nome_original: rawNome,
    nome_normalizado: nomeNorm,
    tokens,
    token_principal: tokens[0] || nomeNorm.split(' ')[0] || nomeNorm || rawNome
  }
}];

function normalize(str) {
  if (!str) return '';
  return String(str)
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9 ]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function tokenize(str) {
  const stop = ['ltda','eireli','epp','me','sa','ss','sociedade','empresa','comercio','comercial','industria','industrial','servico','servicos','solucao','solucoes','grupo','brasil','do','da','de','dos','das','e'];
  return normalize(str).split(' ').filter(t => t.length > 2 && !stop.includes(t));
}

function digits(v) {
  return String(v || '').replace(/\D/g, '');
}

function endereco(cliente) {
  const e = cliente?.enderecos?.[0]?.endereco;
  if (!e) return '';
  return [e.logradouro, e.numero, e.bairro, String(e.nome_cidade || '') + '/' + String(e.estado || '')]
    .filter(Boolean)
    .join(' - ');
}

const ctx = $('Normalizar Nome').first().json || {};
const nomeNorm = ctx.nome_normalizado || '';
const nomeOriginal = ctx.nome_original || '';
const tokensInput = Array.isArray(ctx.tokens) ? ctx.tokens : [];
const queryDigits = digits(nomeOriginal);

const allItems = $input.all();
const seen = new Set();
const clientes = [];

for (const item of allItems) {
  const rows = item.json?.data || [];
  for (const c of rows) {
    if (!c || seen.has(c.id)) continue;
    seen.add(c.id);
    clientes.push(c);
  }
}

function score(cliente) {
  const nome = normalize(cliente.nome || '');
  const razao = normalize(cliente.razao_social || '');
  const fantasia = normalize(cliente.nome_fantasia || '');
  const cpf = digits(cliente.cpf_cnpj || cliente.cnpj || cliente.documento || '');
  const tel = digits(cliente.telefone || cliente.celular || '');

  if ([nome, razao, fantasia].some(v => v && v === nomeNorm)) return 100;

  let s = 0;
  if (nome && nomeNorm && nome.includes(nomeNorm)) s += 45;
  if (nome && nomeNorm && nomeNorm.includes(nome)) s += 45;
  if (razao && nomeNorm && razao.includes(nomeNorm)) s += 40;
  if (razao && nomeNorm && nomeNorm.includes(razao)) s += 40;
  if (fantasia && nomeNorm && fantasia.includes(nomeNorm)) s += 40;
  if (fantasia && nomeNorm && nomeNorm.includes(fantasia)) s += 40;

  const tokensCliente = [...new Set([
    ...tokenize(cliente.nome || ''),
    ...tokenize(cliente.razao_social || ''),
    ...tokenize(cliente.nome_fantasia || '')
  ])];

  for (const token of tokensInput) {
    if (tokensCliente.some(tc => tc === token)) s += 12;
    else if (tokensCliente.some(tc => tc.includes(token) || token.includes(tc))) s += 8;
  }

  if (tokensInput[0] && tokensCliente.some(tc => tc.includes(tokensInput[0]) || tokensInput[0].includes(tc))) s += 10;
  if (queryDigits && cpf && cpf.includes(queryDigits)) s += 20;
  if (queryDigits && tel && tel.includes(queryDigits)) s += 6;

  return Math.min(s, 100);
}

const ranked = clientes
  .map(c => ({ ...c, _score: score(c) }))
  .filter(c => c._score > 0)
  .sort((a, b) => b._score - a._score);

const option_map = {};
ranked.forEach((c, idx) => {
  option_map[String(idx + 1)] = { id: String(c.id), nome: c.nome || '', score: c._score };
});

const toCliente = (c) => ({
  cliente_id: String(c.id),
  cliente_nome: c.nome || '',
  razao_social: c.razao_social || '',
  nome_fantasia: c.nome_fantasia || '',
  cpf_cnpj: c.cpf_cnpj || c.cnpj || c.documento || '',
  telefone: c.telefone || c.celular || '',
  endereco: endereco(c),
  score: c._score
});

if (ranked.length === 0 || ranked[0]._score < 70) {
  return [{
    json: {
      status: 'not_found',
      resultado: 'Nenhum cliente encontrado para "' + nomeOriginal + '".',
      clientes: [],
      total_encontrado: 0,
      option_map
    }
  }];
}

const top = ranked[0];
const second = ranked[1] || null;
const exactMatch = [normalize(top.nome || ''), normalize(top.razao_social || ''), normalize(top.nome_fantasia || '')].some(v => v === nomeNorm);
const clearSingle = exactMatch || (tokensInput.length >= 2 && top._score >= 90 && (!second || (top._score - second._score) >= 15));

if (clearSingle) {
  return [{
    json: {
      status: 'single_match',
      resultado: 'Cliente confirmado: ' + (top.nome || top.razao_social || top.nome_fantasia || 'registro selecionado') + '.',
      cliente_id: String(top.id),
      cliente_nome: top.nome || '',
      clientes: [toCliente(top)],
      total_encontrado: 1,
      option_map,
      score: top._score
    }
  }];
}

return [{
  json: {
    status: 'multiple_matches',
    resultado: 'Encontrei ' + ranked.length + ' clientes parecidos para "' + nomeOriginal + '".',
    clientes: ranked.slice(0, 10).map(toCliente),
    total_encontrado: ranked.length,
    option_map
  }
}];

const input = $input.first().json || {};
const trigger = $('Trigger').first().json || {};
const clientes = Array.isArray(input.clientes) ? input.clientes : [];
const isMultiple = String(input.status || '') === 'multiple_matches';

const listaTexto = isMultiple
  ? [
      'Encontrei clientes parecidos:',
      ...clientes.slice(0, 10).map((c, idx) => (idx + 1) + '. ' + String(c.cliente_nome || c.nome || c.razao_social || 'Cliente') + (c.endereco ? ' - ' + c.endereco : '')),
      '',
      'Informe o numero da opcao correta.'
    ].join('\n')
  : '';

const state = isMultiple ? {
  estado: 'aguardando_escolha_cliente_nova_os',
  cliente_nome_pesquisado: String(input.resultado || '').replace(/^.*?"(.*)".*$/, '$1'),
  option_map: input.option_map || {},
  lista_texto: listaTexto,
  id_conversa: String(trigger.id_conversa || ''),
  tecnico_id: String(trigger.tecnico_id || ''),
  criado_em: new Date().toISOString()
} : null;

return [{ json: {
  ...input,
  lista_texto: listaTexto,
  state_key: 'piccinin_os:vanda_estado:' + String(trigger.tecnico_id || ''),
  should_persist_state: isMultiple,
  state_json: state ? JSON.stringify(state) : '',
  technical_context: {
    tecnico_id: String(trigger.tecnico_id || ''),
    id_conversa: String(trigger.id_conversa || '')
  }
}}];

